/**
 * Lazy math chunk (M6a). KaTeX + mhchem, loaded only when a `math` block or an
 * inline `math` mark mounts. The chunk carries its own stylesheet so the
 * initial bundle stays free of both the library and its CSS.
 *
 * KaTeX output is generated by the library from a validated `tex` string —
 * model content is never treated as HTML.
 */
import { useMemo } from 'react';
import type { ReactNode } from 'react';
import katex from 'katex';
import 'katex/contrib/mhchem';
import 'katex/dist/katex.min.css';

export interface MathRendererProps {
  tex: string;
  display?: boolean;
}

function render(tex: string, display: boolean): string | null {
  try {
    return katex.renderToString(tex, {
      displayMode: display,
      throwOnError: false,
      trust: false,
      strict: 'ignore',
      output: 'html',
    });
  } catch {
    return null;
  }
}

/** Display math block. Falls back to a plain `<code>` for unrenderable TeX. */
export function MathView({ tex, display = true }: MathRendererProps): ReactNode {
  const html = useMemo(() => render(tex, display), [tex, display]);
  if (html === null) {
    return (
      <code className="dg-math-fallback" data-dg-part="fallback">
        {tex}
      </code>
    );
  }
  return (
    <span
      className={display ? 'dg-math dg-math-display' : 'dg-math dg-math-inline'}
      data-dg-part="root"
      // Library-generated KaTeX markup, never model-supplied HTML.
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}

/** Inline math mark. */
export function InlineMathView({ tex }: { tex: string }): ReactNode {
  return <MathView tex={tex} display={false} />;
}

export default MathView;
